package ara.daily;
import android.Manifest;
import android.app.*;
import android.app.job.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

public final class PhoneReminders {
 private static final String CHANNEL="ara_schedule_v1";
 private static final int JOB=8765;
 private static final ExecutorService IO=Executors.newSingleThreadExecutor();
 private static final AtomicBoolean FETCHING=new AtomicBoolean();
 private static volatile long lastAttempt=0;
 private PhoneReminders(){}
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("ara.reminders",Context.MODE_PRIVATE);}
 private static NotificationManager manager(Context c){return (NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);}
 private static JSONObject object(String raw){try{return new JSONObject(raw);}catch(Exception e){return new JSONObject();}}
 public static boolean enabled(Context c){return prefs(c).getBoolean("enabled",true);}
 public static boolean permitted(Context c){if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return false;NotificationManager m=manager(c);NotificationChannel channel=m.getNotificationChannel(CHANNEL);return m.areNotificationsEnabled()&&(channel==null||channel.getImportance()!=NotificationManager.IMPORTANCE_NONE);}
 public static boolean exact(Context c){return Build.VERSION.SDK_INT<31||((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).canScheduleExactAlarms();}
 public static void requestExact(Activity a){if(Build.VERSION.SDK_INT>=31)openSettings(a,new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+a.getPackageName())));}
 private static synchronized void log(Context c,String event,String detail){try{JSONArray old=new JSONArray(prefs(c).getString("diagnostics","[]")),next=new JSONArray();for(int i=Math.max(0,old.length()-79);i<old.length();i++)next.put(old.get(i));JSONObject entry=new JSONObject();entry.put("at",System.currentTimeMillis());entry.put("event",event);entry.put("detail",detail);next.put(entry);prefs(c).edit().putString("diagnostics",next.toString()).apply();}catch(Exception ignored){}}
 public static String diagnostics(Context c){return prefs(c).getString("diagnostics","[]");}
 public static void initialize(Context c){NotionDiarySync.initialize(c);NotificationChannel channel=new NotificationChannel(CHANNEL,"ARA 일정 알림",NotificationManager.IMPORTANCE_DEFAULT);channel.setDescription("끼니·운동·소등 시간을 일반 알림으로 알려 줍니다.");channel.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);manager(c).createNotificationChannel(channel);if(enabled(c)){restore(c);job(c);}}
 public static void permission(Activity a){if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED&&!prefs(a).getBoolean("permissionAsked",false)){prefs(a).edit().putBoolean("permissionAsked",true).apply();a.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},42);}}
 private static void openSettings(Activity a,Intent intent){try{a.startActivity(intent);}catch(ActivityNotFoundException|SecurityException e){try{a.startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.getPackageName())));}catch(ActivityNotFoundException|SecurityException ignored){log(a,"settings-unavailable",intent.getAction());}}}
 public static void requestPermission(Activity a){if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED&&(!prefs(a).getBoolean("permissionAsked",false)||a.shouldShowRequestPermissionRationale(Manifest.permission.POST_NOTIFICATIONS))){prefs(a).edit().putBoolean("permissionAsked",true).apply();a.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},42);}else openSettings(a,new Intent(manager(a).areNotificationsEnabled()?android.provider.Settings.ACTION_CHANNEL_NOTIFICATION_SETTINGS:android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,a.getPackageName()).putExtra(android.provider.Settings.EXTRA_CHANNEL_ID,CHANNEL));}
 public static void local(Context c,String text){if(text==null||text.length()>1024*1024)return;try{JSONArray items=new JSONObject(text).getJSONArray("items");prefs(c).edit().putBoolean("localMode",true).apply();((JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).cancel(JOB);replace(c,items);prefs(c).edit().putLong("lastSync",System.currentTimeMillis()).putString("error","").apply();}catch(Exception e){log(c,"local-feed-failed",e.getClass().getSimpleName());}}
 public static void configure(Context c,String server,String token){if(!MainActivity.local(server)||token==null||!token.matches("[a-f0-9]{64}"))return;String old=prefs(c).getString("server","");if(!old.isEmpty()&&!old.equals(server)){replace(c,new JSONArray());prefs(c).edit().remove("delivered").apply();}prefs(c).edit().putString("server",server).putString("token",token).apply();if(enabled(c)){job(c);refresh(c);}}
 public static void setEnabled(Context c,boolean value){prefs(c).edit().putBoolean("enabled",value).apply();if(value){initialize(c);refresh(c);}else{cancelAll(c);((JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).cancel(JOB);}}
 public static String status(Context c){JSONObject result=new JSONObject();try{long now=System.currentTimeMillis(),next=Long.MAX_VALUE;int count=0;JSONObject items=object(prefs(c).getString("items","{}")),sent=object(prefs(c).getString("delivered","{}"));for(String key:keys(items)){JSONObject item=items.optJSONObject(key);if(item!=null&&!sent.has(key)&&ReminderPolicy.current(item.optLong("at"),item.optLong("expires"),now)){count++;next=Math.min(next,item.optLong("at"));}}result.put("batteryExempt",((PowerManager)c.getSystemService(Context.POWER_SERVICE)).isIgnoringBatteryOptimizations(c.getPackageName()));result.put("powerSave",((PowerManager)c.getSystemService(Context.POWER_SERVICE)).isPowerSaveMode());result.put("restricted",Build.VERSION.SDK_INT>=28&&((ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).isBackgroundRestricted());result.put("lastDeliveredAt",prefs(c).getLong("lastDeliveredAt",0));result.put("lastDelayMs",prefs(c).getLong("lastDelayMs",0));result.put("enabled",enabled(c));result.put("permission",permitted(c));result.put("exact",exact(c));result.put("lastSync",prefs(c).getLong("lastSync",0));result.put("scheduled",count);result.put("nextAt",next==Long.MAX_VALUE?0:next);result.put("error",prefs(c).getString("error",""));}catch(Exception ignored){}return result.toString();}
 public static void job(Context c){if(prefs(c).getBoolean("localMode",false)||!enabled(c)||prefs(c).getString("token","").isEmpty())return;JobInfo job=new JobInfo.Builder(JOB,new ComponentName(c,SyncJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000L).setPersisted(true).build();((JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).schedule(job);}
 public static void refresh(Context context){final Context c=context.getApplicationContext();long now=SystemClock.elapsedRealtime();if(now-lastAttempt<10000||!enabled(c)||!FETCHING.compareAndSet(false,true))return;lastAttempt=now;IO.execute(()->{try{fetch(c);}finally{FETCHING.set(false);}});}
 private static void fetch(Context c){if(prefs(c).getBoolean("localMode",false))return;String server=prefs(c).getString("server",""),token=prefs(c).getString("token","");if(!MainActivity.local(server)||!token.matches("[a-f0-9]{64}"))return;HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL(server+"/api/reminders").openConnection(Proxy.NO_PROXY);connection.setConnectTimeout(3500);connection.setReadTimeout(5500);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Authorization","Bearer "+token);if(connection.getResponseCode()!=200)throw new IOException("PC 연결을 확인해 주세요.");try(InputStream input=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] data=new byte[4096];int n,total=0;while((n=input.read(data))!=-1){total+=n;if(total>1024*1024)throw new IOException("응답 범위 초과");out.write(data,0,n);}if(prefs(c).getBoolean("localMode",false)||!enabled(c)||!server.equals(prefs(c).getString("server",""))||!token.equals(prefs(c).getString("token","")))return;JSONArray feed=new JSONObject(out.toString("UTF-8")).getJSONArray("items");replace(c,feed);log(c,"sync","items="+feed.length());prefs(c).edit().putLong("lastSync",System.currentTimeMillis()).putString("error","").apply();}}catch(Exception e){log(c,"sync-failed",e.getClass().getSimpleName());prefs(c).edit().putString("error","마지막으로 받은 일정으로 알림을 유지합니다. PC와 같은 Wi-Fi에서 다시 연결하세요.").apply();}finally{if(connection!=null)connection.disconnect();}}
 private static PendingIntent intent(Context c,String key){Intent i=new Intent(c,Receiver.class).setData(Uri.parse("aradaily://notice/"+Uri.encode(key))).putExtra("key",key);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static Set<String> keys(JSONObject map){Set<String> result=new HashSet<>();Iterator<String> i=map.keys();while(i.hasNext())result.add(i.next());return result;}
 public static synchronized void replace(Context c,JSONArray items){JSONObject old=object(prefs(c).getString("items","{}")),next=new JSONObject();long now=System.currentTimeMillis();for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String key=item.optString("key");if(key.isEmpty()||key.length()>500||!ReminderPolicy.current(item.optLong("at"),item.optLong("expires"),now))continue;try{next.put(key,item);}catch(Exception ignored){}}
  AlarmManager alarm=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(String test:keys(old))if(test.startsWith("scheduled-test|")&&ReminderPolicy.current(old.optJSONObject(test).optLong("at"),old.optJSONObject(test).optLong("expires"),now))try{next.put(test,old.optJSONObject(test));}catch(Exception ignored){}for(String key:ReminderPolicy.removed(keys(old),keys(next))){alarm.cancel(intent(c,key));manager(c).cancel(key.hashCode());}prefs(c).edit().putString("items",next.toString()).apply();for(String key:keys(next)){JSONObject item=next.optJSONObject(key),previous=old.optJSONObject(key);PendingIntent existing=PendingIntent.getBroadcast(c,0,new Intent(c,Receiver.class).setData(Uri.parse("aradaily://notice/"+Uri.encode(key))),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(previous==null||existing==null||previous.optLong("at")!=item.optLong("at")||previous.optLong("expires")!=item.optLong("expires")||item.optLong("at")<=now||prefs(c).getBoolean("scheduledExact",false)!=exact(c))schedule(c,key,item);}
 prefs(c).edit().putBoolean("scheduledExact",exact(c)).apply();
 }
 private static void schedule(Context c,String key,JSONObject item){if(!enabled(c)||!permitted(c)||item==null)return;JSONObject sent=object(prefs(c).getString("delivered","{}"));if(sent.has(key))return;long now=System.currentTimeMillis(),at=item.optLong("at"),expires=item.optLong("expires");if(!ReminderPolicy.current(at,expires,now))return;if(at<=now){deliver(c,key);return;}AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(exact(c)){try{alarms.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,intent(c,key));log(c,"scheduled-exact",item.optString("title")+" at="+at);return;}catch(SecurityException denied){log(c,"exact-denied","fallback=inexact");}}alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,intent(c,key));log(c,"scheduled-inexact",item.optString("title")+" at="+at);}
 private static void restore(Context c){JSONObject items=object(prefs(c).getString("items","{}"));for(String key:keys(items))schedule(c,key,items.optJSONObject(key));}
 private static void cancelAll(Context c){JSONObject items=object(prefs(c).getString("items","{}"));AlarmManager alarm=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(String key:keys(items)){alarm.cancel(intent(c,key));manager(c).cancel(key.hashCode());}}
 public static synchronized void deliver(Context c,String key){if(key==null)return;JSONObject item=object(prefs(c).getString("items","{}")).optJSONObject(key);if(item==null)return;JSONObject sent=object(prefs(c).getString("delivered","{}"));long now=System.currentTimeMillis();if(!enabled(c)||!ReminderPolicy.deliver(item.optLong("at"),item.optLong("expires"),now,sent.has(key),permitted(c))){log(c,"not-posted","enabled="+enabled(c)+" permission="+permitted(c)+" delivered="+sent.has(key)+" latenessMs="+(now-item.optLong("at")));return;}try{post(c,key.hashCode(),item.optString("title"),item.optString("body"));log(c,"posted",item.optString("title")+" latenessMs="+(now-item.optLong("at")));prefs(c).edit().putLong("lastDeliveredAt",now).putLong("lastDelayMs",Math.max(0,now-item.optLong("at"))).apply();sent.put(key,now);for(String old:new HashSet<>(keys(sent)))if(sent.optLong(old)<now-3*86400000L)sent.remove(old);prefs(c).edit().putString("delivered",sent.toString()).apply();}catch(Exception e){prefs(c).edit().putString("error","알림 권한을 확인해 주세요.").apply();}}
 private static void post(Context c,int id,String title,String body){Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent tap=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(c,CHANNEL).setSmallIcon(ara.daily.R.drawable.ic_notification).setColor(0xff27694f).setContentTitle(title).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setCategory(Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PRIVATE).setOnlyAlertOnce(true).setAutoCancel(true).setContentIntent(tap).build();manager(c).notify(id,notification);}
 public static void openBatterySettings(Activity a){openSettings(a,new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.getPackageName())));}
 public static synchronized void scheduledTest(Context c){try{long at=System.currentTimeMillis()+60000;String key="scheduled-test|"+at;JSONObject item=new JSONObject();item.put("key",key);item.put("title","ARA 1분 예약 테스트");item.put("body","예약 시각 "+new java.text.SimpleDateFormat("HH:mm:ss",Locale.KOREA).format(new Date(at))+" · 즉시 테스트와 달리 Android 예약 전달을 확인합니다.");item.put("at",at);item.put("expires",at+3600000);JSONObject items=object(prefs(c).getString("items","{}"));items.put(key,item);prefs(c).edit().putString("items",items.toString()).apply();schedule(c,key,item);}catch(Exception e){log(c,"test-schedule-failed",e.getClass().getSimpleName());}}
 public static void test(Context c){if(permitted(c))post(c,4242,"ARA 알림 테스트","일반 알림입니다. 시작·정지 버튼 없이 나중에 기록하면 됩니다.");}
 public static class Receiver extends BroadcastReceiver {@Override public void onReceive(Context c,Intent i){if(i!=null)deliver(c,i.getStringExtra("key"));}}
 public static class BootReceiver extends BroadcastReceiver {@Override public void onReceive(Context c,Intent i){if(i!=null&&(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())||Intent.ACTION_MY_PACKAGE_REPLACED.equals(i.getAction())||AlarmManager.ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED.equals(i.getAction())||Intent.ACTION_TIME_CHANGED.equals(i.getAction())||Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction())))initialize(c);}}
 public static class SyncJob extends JobService {@Override public boolean onStartJob(JobParameters p){IO.execute(()->{try{fetch(this);}finally{jobFinished(p,false);}});return true;}@Override public boolean onStopJob(JobParameters p){return true;}}
}
